import{_ as t,o,c as a,a2 as s}from"./chunks/framework.9yf7n3zg.js";const u=JSON.parse('{"title":"FAQ and troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":1792171429000}'),r={name:"reference/faq.md"};function n(i,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="faq-and-troubleshooting" tabindex="-1">FAQ and troubleshooting <a class="header-anchor" href="#faq-and-troubleshooting" aria-label="Permalink to &quot;FAQ and troubleshooting&quot;">​</a></h1><p>Answers to the questions writers ask most, and what to do when Leathercase shows a message you did not expect. Most answers about how your folder is read can be checked against your own story: open <strong>How this story is read</strong> from the breadcrumb&#39;s view menu, or press <code>Ctrl+K</code> (<code>Cmd+K</code> on macOS) and type its name. It lists what Leathercase found, what it left out and why, and offers a fix where something looks off.</p><h2 id="the-basics" tabindex="-1">The basics <a class="header-anchor" href="#the-basics" aria-label="Permalink to &quot;The basics&quot;">​</a></h2><h3 id="will-it-change-my-files" tabindex="-1">Will it change my files? <a class="header-anchor" href="#will-it-change-my-files" aria-label="Permalink to &quot;Will it change my files?&quot;">​</a></h3><p>No. Leathercase reads your manuscript and your notes and never writes into them: not a heading, not a property, not a comma. It writes only its own files, in folders named <code>suite/</code>, in <code>Writer/</code> for the cards you make, and in <code>Suite.md</code> at the root of your writing home. <a href="/guide/reference/suite-files">Files Leathercase writes</a> lists every one.</p><p>Even its own Markdown files are written with care: the old version is kept in a hidden <code>.history/</code> folder before each change, and a file Leathercase cannot read is left alone rather than overwritten.</p><h3 id="does-it-work-with-obsidian-scrivener-word-or-final-draft" tabindex="-1">Does it work with Obsidian, Scrivener, Word or Final Draft? <a class="header-anchor" href="#does-it-work-with-obsidian-scrivener-word-or-final-draft" aria-label="Permalink to &quot;Does it work with Obsidian, Scrivener, Word or Final Draft?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Your app</th><th>Works</th></tr></thead><tbody><tr><td>Obsidian</td><td>Yes. Point Leathercase at your vault or a folder inside it. Front matter, <code>[[links]]</code>, aliases and <code>%% comments %%</code> are read, and a passage opens in Obsidian at its heading</td></tr><tr><td>Scrivener 2 and 3</td><td>Yes. Leathercase reads the <code>.scriv</code> project&#39;s binder and texts. A passage opens the project in Scrivener</td></tr><tr><td>Microsoft Word, LibreOffice Writer</td><td>Yes, <code>.docx</code> files. Use Word&#39;s Heading styles for scenes</td></tr><tr><td>Google Docs, Pages</td><td>Download or export as <code>.docx</code> into your writing home</td></tr><tr><td>Highland, Fade In, Slugline, Beat</td><td>Yes, <code>.fountain</code> files</td></tr><tr><td>Final Draft</td><td>Export the script as Fountain</td></tr><tr><td>iA Writer, Typora, Ulysses, Bear, any text editor</td><td>Yes, <code>.md</code> files (export from Ulysses or Bear first)</td></tr></tbody></table><p>You keep writing in your own app. See <a href="/guide/reference/formats">Files Leathercase reads</a>.</p><h3 id="can-i-keep-writing-while-leathercase-is-open" tabindex="-1">Can I keep writing while Leathercase is open? <a class="header-anchor" href="#can-i-keep-writing-while-leathercase-is-open" aria-label="Permalink to &quot;Can I keep writing while Leathercase is open?&quot;">​</a></h3><p>Yes, that is how it is meant to be used. Leathercase watches your story&#39;s folder and reads a save within moments; the title bar says when the story was last read, and the Desk says what changed.</p><h3 id="do-i-need-an-account-or-an-internet-connection" tabindex="-1">Do I need an account or an internet connection? <a class="header-anchor" href="#do-i-need-an-account-or-an-internet-connection" aria-label="Permalink to &quot;Do I need an account or an internet connection?&quot;">​</a></h3><p>No. Leathercase works offline, with no account. It goes online only when you ask it to check for updates or to download the meaning search model. See <a href="/guide/reference/privacy">Privacy</a>.</p><h3 id="is-my-writing-sent-to-an-ai" tabindex="-1">Is my writing sent to an AI? <a class="header-anchor" href="#is-my-writing-sent-to-an-ai" aria-label="Permalink to &quot;Is my writing sent to an AI?&quot;">​</a></h3><p>Not by Leathercase. The mate, Leathercase&#39;s own assistant, runs on your computer and wakes no model. An outside agent such as Claude Desktop reads your stories only if you connect it and only the homes you grant; what its own app does with what it reads is up to that app. See <a href="/guide/guide/connect-an-agent">Connect an agent</a>.</p><h3 id="can-i-sync-it-or-use-it-on-two-computers" tabindex="-1">Can I sync it, or use it on two computers? <a class="header-anchor" href="#can-i-sync-it-or-use-it-on-two-computers" aria-label="Permalink to &quot;Can I sync it, or use it on two computers?&quot;">​</a></h3><p>Yes. Everything Leathercase keeps for your stories lives in your writing home, beside them. Put the home in Dropbox, iCloud Drive, OneDrive, Google Drive or a git repository and open it on each computer; its stories open as they were left. If two computers change the same Leathercase file before they sync, <strong>Settings</strong>, <strong>Storage</strong> lists the conflicted copy under <strong>Conflicts</strong>, with <strong>Compare</strong>, <strong>Keep this computer&#39;s</strong> and <strong>Keep the copy</strong>. See <a href="/guide/reference/suite-files#syncing-with-dropbox-icloud-drive-onedrive-google-drive-or-git">Files Leathercase writes</a>.</p><h3 id="which-systems-does-it-run-on" tabindex="-1">Which systems does it run on? <a class="header-anchor" href="#which-systems-does-it-run-on" aria-label="Permalink to &quot;Which systems does it run on?&quot;">​</a></h3><p>Windows (x64 and Arm), macOS 12 or later (Apple silicon and Intel) and Linux (x86_64 and Arm, as an AppImage or a <code>.deb</code>). It is a desktop app; there is no phone version.</p><h2 id="stories-and-scenes" tabindex="-1">Stories and scenes <a class="header-anchor" href="#stories-and-scenes" aria-label="Permalink to &quot;Stories and scenes&quot;">​</a></h2><h3 id="why-is-my-scene-missing-from-the-plot-grid" tabindex="-1">Why is my scene missing from the plot grid? <a class="header-anchor" href="#why-is-my-scene-missing-from-the-plot-grid" aria-label="Permalink to &quot;Why is my scene missing from the plot grid?&quot;">​</a></h3><p>Go through these in order; <strong>How this story is read</strong> shows most of them for your own story.</p><ol><li><strong>The grid has not taken it yet.</strong> The grid is its own file, <code>PlotGrid.md</code>, made from the story the first time it opened. It never changes by itself: a scene you write later shows as <strong>new in the story</strong>, and the grid asks what it becomes: <strong>Put it in the grid where the story&#39;s order puts it</strong>, <strong>It is the planned scene…</strong>, <strong>Leave it out of the grid</strong>, or <strong>Not a scene</strong>. Choose <strong>Decide later</strong> and it waits. If you once chose <strong>Leave it out of the grid</strong>, the grid file keeps a <code>left out:</code> comment for it.</li><li><strong>The file is not read as prose.</strong> Only the files declared as the story&#39;s prose make scenes. A file added after you declared the story, in a folder nothing claims, waits as <strong>unsorted</strong>, and Leathercase asks what it is. Answer the question, or say what the folder holds in <strong>Story settings</strong>. See <a href="/guide/guide/how-a-story-is-read">How a story is read</a>.</li><li><strong>It has no heading.</strong> Leathercase splits scenes only at headings, never at <code>---</code>, <code>* * *</code> or blank lines. A file with no heading is one scene, named after the file. <strong>How this story is read</strong> says so under <strong>What looks off</strong>: &quot;has 2,400 words and no heading, so it is read as one scene.&quot;</li><li><strong>The heading is not a heading to Leathercase.</strong> It sits inside a <code>%% comment %%</code>, an <code>&lt;!-- comment --&gt;</code> or a code fence. In Word, it is bold Normal text rather than a Heading style.</li><li><strong>The file is left out.</strong> An ignore pattern in <strong>Story settings</strong> matches it, its front matter says <code>creative-writer: false</code>, it sits in a hidden folder or a <code>suite/</code> folder, or it is the story&#39;s note (with <code>story: true</code> or a <code>writing-target</code>). <strong>How this story is read</strong> lists it under <strong>Notes left out</strong>, with the reason.</li><li><strong>The file is typed.</strong> A note with <code>type: character</code>, or one in a <code>Characters/</code> or <code>Places/</code> folder, is part of the cast, never a scene.</li><li><strong>The format is not read.</strong> <code>.doc</code>, <code>.odt</code>, <code>.rtf</code>, <code>.txt</code> and <code>.pdf</code> files are listed and left alone. Save the chapter as <code>.docx</code> or <code>.md</code>.</li></ol><p><code>manuscript: false</code> keeps a note off the manuscript page only; it does not affect the grid.</p><h3 id="why-are-two-scenes-read-as-one-or-one-scene-as-two" tabindex="-1">Why are two scenes read as one, or one scene as two? <a class="header-anchor" href="#why-are-two-scenes-read-as-one-or-one-scene-as-two" aria-label="Permalink to &quot;Why are two scenes read as one, or one scene as two?&quot;">​</a></h3><p>Every heading starts a scene, at any level, and a scene runs to the next heading. Give each scene its own heading to split it; remove a heading (or make it plain text) to join two. A heading with no prose under it yet is a scene planned, not written.</p><h3 id="i-kept-an-outline-md-where-did-my-planned-scenes-go" tabindex="-1">I kept an Outline.md; where did my planned scenes go? <a class="header-anchor" href="#i-kept-an-outline-md-where-did-my-planned-scenes-go" aria-label="Permalink to &quot;I kept an Outline.md; where did my planned scenes go?&quot;">​</a></h3><p>Into the plot grid&#39;s own file. The first time Leathercase read the story, it made <code>PlotGrid.md</code> in the story&#39;s <code>suite/</code> folder and carried in the planned scenes of an <code>Outline.md</code> it found in the story&#39;s folder (or its <code>suite/</code> folder). <code>Outline.md</code> is read only that once and never written: it stays where it was, unchanged. A planned scene you add from then on, with <strong>New scene</strong>, <strong>Plan a scene</strong> or a beat card sent to the grid, goes into <code>PlotGrid.md</code>. Carried scenes for a chapter you have since written are marked <strong>from the old outline</strong>; see <a href="/guide/guide/plot-grid#settling-the-old-outline">Plot grid</a>.</p><h3 id="my-research-notes-show-up-as-scenes" tabindex="-1">My research notes show up as scenes <a class="header-anchor" href="#my-research-notes-show-up-as-scenes" aria-label="Permalink to &quot;My research notes show up as scenes&quot;">​</a></h3><p>Notes about the story, such as memos, research and reviews, are not scenes. Leave the folder out with an ignore pattern in <strong>Story settings</strong>, such as <code>_Work/**</code>, or say what the folder holds when Leathercase asks: plan, record, work notes, research or scraps. Folders called <code>Research/</code>, <code>Outline/</code>, <code>Journal/</code>, <code>Cuts/</code> and their equivalents in five other languages are recognised by name. <strong>How this story is read</strong> offers <strong>Leave <code>_Work/**</code> out</strong> as a fix when it finds such a folder read as story.</p><h3 id="a-character-note-shows-up-as-a-scene" tabindex="-1">A character note shows up as a scene <a class="header-anchor" href="#a-character-note-shows-up-as-a-scene" aria-label="Permalink to &quot;A character note shows up as a scene&quot;">​</a></h3><p>Leathercase did not know it was a character. Put it in a <code>Characters/</code> folder (or <code>People/</code>, <code>Cast/</code>, <code>Personagens/</code> and so on), or add <code>type: character</code> to its front matter. See <a href="/guide/reference/front-matter#type-what-a-note-is">Front matter</a>.</p><h3 id="leathercase-keeps-asking-what-some-files-are" tabindex="-1">Leathercase keeps asking what some files are <a class="header-anchor" href="#leathercase-keeps-asking-what-some-files-are" aria-label="Permalink to &quot;Leathercase keeps asking what some files are&quot;">​</a></h3><p>Those files are <strong>unsorted</strong>: nothing says what they are, or their <code>type:</code> is a word the story does not know. They are never scenes until you say so. Answer once and every file like them is settled, including ones you write later; choose <strong>Later</strong> to be asked again, or <strong>Don&#39;t ask again</strong> to leave them unsorted for good.</p><h3 id="the-story-says-its-folder-was-not-found" tabindex="-1">The story says its folder was not found <a class="header-anchor" href="#the-story-says-its-folder-was-not-found" aria-label="Permalink to &quot;The story says its folder was not found&quot;">​</a></h3><p>The Desk shows <strong>The story&#39;s folder was not found</strong> and &quot;moved, renamed or not mounted&quot; when the folder is not where the home says. If you moved or renamed it, choose <strong>Find it</strong> and point at the new place: the story&#39;s <code>suite/</code> folder moved with it, so everything comes back. If it lives on an external or network drive, connect the drive.</p><h3 id="the-title-bar-says-the-folder-cannot-be-read" tabindex="-1">The title bar says the folder cannot be read <a class="header-anchor" href="#the-title-bar-says-the-folder-cannot-be-read" aria-label="Permalink to &quot;The title bar says the folder cannot be read&quot;">​</a></h3><p><strong>The story&#39;s folder cannot be read. The views show the last reading.</strong> The folder was removed, unmounted, or its permissions changed. Everything you see is the last good reading; nothing is lost. Reconnect the drive or restore the folder.</p><h3 id="the-title-bar-says-leathercase-looks-for-saves-every-few-seconds" tabindex="-1">The title bar says Leathercase looks for saves every few seconds <a class="header-anchor" href="#the-title-bar-says-leathercase-looks-for-saves-every-few-seconds" aria-label="Permalink to &quot;The title bar says Leathercase looks for saves every few seconds&quot;">​</a></h3><p><strong>The system cannot tell of saves here, so Leathercase looks for them every few seconds.</strong> Some network drives and sync folders do not report changes. Leathercase works the same; a save shows a few seconds later.</p><h3 id="my-scrivener-changes-do-not-show" tabindex="-1">My Scrivener changes do not show <a class="header-anchor" href="#my-scrivener-changes-do-not-show" aria-label="Permalink to &quot;My Scrivener changes do not show&quot;">​</a></h3><p>Leathercase reads what is on disk, and Scrivener writes its project when it saves. Save in Scrivener (or wait for its autosave) and the change shows.</p><h3 id="the-exported-book-says-chapter-in-a-portuguese-story" tabindex="-1">The exported book says &quot;Chapter&quot; in a Portuguese story <a class="header-anchor" href="#the-exported-book-says-chapter-in-a-portuguese-story" aria-label="Permalink to &quot;The exported book says &quot;Chapter&quot; in a Portuguese story&quot;">​</a></h3><p>The book&#39;s words follow the story&#39;s language, which Leathercase tells from the prose until you set it. Set it in <strong>Story settings</strong>, <strong>Language</strong>. See <a href="/guide/reference/languages">Languages</a>.</p><h2 id="names-and-the-graph" tabindex="-1">Names and the Graph <a class="header-anchor" href="#names-and-the-graph" aria-label="Permalink to &quot;Names and the Graph&quot;">​</a></h2><h3 id="why-is-a-name-not-in-the-graph" tabindex="-1">Why is a name not in the Graph? <a class="header-anchor" href="#why-is-a-name-not-in-the-graph" aria-label="Permalink to &quot;Why is a name not in the Graph?&quot;">​</a></h3><p>A character, place or thing is in the Graph when it has a note (typed by <code>type:</code> or by its folder), or when the prose names it three times or more without one; the second kind shows dashed, as a candidate. A name may be missing because:</p><ul><li><strong>It has no note and appears fewer than three times.</strong> Write its note, or make one from the find field.</li><li><strong>You told Leathercase it is not a name.</strong> Words you dismissed in the Graph, and the plugin&#39;s <code>story-ignore:</code> list, are kept in <strong>Story settings</strong> as ignored names. Remove it there.</li><li><strong>It only ever starts a sentence.</strong> A capital at the start of a sentence counts only for names Leathercase already knows, so &quot;Rain fell&quot; is not a person called Rain.</li><li><strong>It is a common word or a title.</strong> Pronouns, honorifics, months, days and the like are never names, in any of the six languages Leathercase reads.</li><li><strong>Two notes share it.</strong> &quot;Vidal&quot; alone does not resolve when Nora Vidal and Tomás Vidal both have notes; the full name, or an alias, does.</li><li><strong>It sits only in notes left out of the story,</strong> such as research notes.</li><li><strong>The tab hides its kind.</strong> A graph tab can show some kinds only, such as characters for a Truby tab; <strong>Whole story</strong> shows them all, unless you changed what it shows.</li></ul><h3 id="the-graph-shows-a-word-that-is-not-a-name" tabindex="-1">The Graph shows a word that is not a name <a class="header-anchor" href="#the-graph-shows-a-word-that-is-not-a-name" aria-label="Permalink to &quot;The Graph shows a word that is not a name&quot;">​</a></h3><p>Pin it in the Graph and say it is not a name. Leathercase keeps that in <strong>Story settings</strong>, never in a note.</p><h3 id="the-graph-shows-nora-and-nora-vidal-as-two-people" tabindex="-1">The Graph shows Nora and Nora Vidal as two people <a class="header-anchor" href="#the-graph-shows-nora-and-nora-vidal-as-two-people" aria-label="Permalink to &quot;The Graph shows Nora and Nora Vidal as two people&quot;">​</a></h3><p>Tell Leathercase they are one: add <code>aliases: [Nora]</code> to Nora Vidal&#39;s note, or confirm in the Graph that Nora is another name for Nora Vidal. The second is kept in <strong>Story settings</strong> and never written into your note. A first name or surname that only one note has finds that note on its own.</p><h3 id="she-is-read-as-the-wrong-character" tabindex="-1">&quot;She&quot; is read as the wrong character <a class="header-anchor" href="#she-is-read-as-the-wrong-character" aria-label="Permalink to &quot;&quot;She&quot; is read as the wrong character&quot;">​</a></h3><p>Leathercase reads she and he back to the nearest character it knows with that pronoun. Set a character&#39;s pronoun with <code>pronouns: she/her</code> in their note, or in the Graph. It does not know an epithet, so &quot;the boy&quot; is not read as Zak.</p><h2 id="messages-you-may-see" tabindex="-1">Messages you may see <a class="header-anchor" href="#messages-you-may-see" aria-label="Permalink to &quot;Messages you may see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td>&quot;<code>file</code>&quot; cannot be read, so Leathercase leaves it as it is rather than write over it. Mend it by hand, or wait for your sync to finish, then try again.</td><td>One of Leathercase&#39;s own files is half synced or was broken by a hand edit</td><td>Wait for your sync, or open the file and mend it; <a href="/guide/reference/suite-files#kept-versions">kept versions</a> and daily snapshots hold earlier copies</td></tr><tr><td>&quot;<code>folder</code>&quot; is your whole home folder and cannot be a writing home.</td><td>You picked your user folder</td><td>Pick the folder inside it that holds your stories</td></tr><tr><td>&quot;<code>folder</code>&quot; is the root of a drive and cannot be a writing home.</td><td>You picked a drive</td><td>Pick the folder that holds your stories</td></tr><tr><td>&quot;<code>folder</code>&quot; belongs to the system and cannot be a writing home.</td><td>You picked a system folder</td><td>Pick a folder of your own</td></tr><tr><td>&quot;<code>folder</code>&quot; is where Leathercase keeps its own data and cannot be a writing home.</td><td>You picked the app&#39;s data folder</td><td>Pick a folder of your own</td></tr><tr><td>The folder &quot;<code>folder</code>&quot; already holds the story &quot;<code>story</code>&quot;.</td><td>Two stories cannot share a folder, since each folder holds one <code>suite/</code></td><td>Choose another folder, or open the existing story</td></tr><tr><td>That folder is outside the home; a story lives inside its home&#39;s folder.</td><td>A story&#39;s folder must be inside the writing home</td><td>Move the story into the home, or add its folder as another home</td></tr><tr><td>A story needs a working title.</td><td>The name is empty</td><td>Type a working title</td></tr><tr><td>&quot;<code>title</code>&quot; cannot be a story&#39;s folder: a name of only dots or spaces is the home itself, or the folder above it.</td><td>The title would make an impossible folder name</td><td>Give the story a title with a letter in it</td></tr><tr><td><code>path</code> is outside every declared story; declare its folder to open it from here.</td><td>You tried to open a file no story reads</td><td>Declare its folder as a story, or open it in your own app</td></tr><tr><td>The grid file changed outside the app since the grid was shown, and the row this change was for is no longer in it. Nothing was written; the grid now shows the file as it is.</td><td>You or a sync edited <code>PlotGrid.md</code> meanwhile</td><td>Make the change again on the grid as it is now</td></tr><tr><td>This story has no Fountain files: the Fountain export gives a script back as it was written. Choose another format for it in Settings › Export.</td><td>The story was exported as Fountain but is not written in Fountain</td><td>Pick Word, PDF, EPUB or Markdown in <strong>Settings › Export</strong></td></tr><tr><td>Open a writing home first; a capture lands in its Writer.</td><td><strong>Capture to Writer</strong> has no home to send to</td><td>Open or add a writing home</td></tr><tr><td>No home is open.</td><td>An action needs a home</td><td>Open or add a writing home</td></tr><tr><td>Leathercase did not start cleanly</td><td>A step of the start failed; the detail says which</td><td>Quit and open Leathercase again</td></tr><tr><td>Leathercase could not reach its releases. Check the connection and try again.</td><td>The update check could not go online</td><td>Check your connection, then <strong>Try again</strong></td></tr><tr><td>This copy of Leathercase cannot check for updates. Newer versions are on the download page.</td><td>This kind of install has no update feed</td><td>Download new versions from the releases page</td></tr><tr><td>The download did not finish: …</td><td>The meaning search model&#39;s download stopped</td><td><strong>Try again</strong>; it resumes where it stopped</td></tr><tr><td>3 anchors no longer match their prose</td><td>A thread stop, comment or cell quotes a sentence you have since changed</td><td>Open the manuscript and step through the broken anchors; re-anchor or remove each one</td></tr></tbody></table><h2 id="undoing-and-recovering" tabindex="-1">Undoing and recovering <a class="header-anchor" href="#undoing-and-recovering" aria-label="Permalink to &quot;Undoing and recovering&quot;">​</a></h2><ul><li><strong>On the grid</strong>, <code>Ctrl+Z</code> (<code>Cmd+Z</code>) undoes the last change, whole, and <code>Ctrl+Shift+Z</code> redoes it. An undo leaves alone a file you changed outside Leathercase since.</li><li><strong>Earlier versions</strong> of Leathercase&#39;s Markdown files (the grid file, threads, comments, cards, beats) are kept for 30 days in the hidden <code>.history/</code> folder beside each, as plain Markdown.</li><li><strong>Daily snapshots</strong> of every <code>suite/</code> folder are kept for 14 days in the home&#39;s <code>suite/daily/</code>. <strong>Settings</strong>, <strong>Storage</strong>, <strong>Daily snapshots</strong>, <strong>Show</strong> opens the folder. To restore, copy a file back by hand.</li><li><strong>Grid snapshots</strong> of earlier days open as read-only tabs beside <strong>Now</strong> on the plot grid.</li><li><strong>Conflicted copies</strong>: the side you let go of goes to the system&#39;s trash, so nothing is lost.</li><li><strong>Your manuscripts</strong> are your own app&#39;s and your sync tool&#39;s to recover; Leathercase never changed them.</li></ul><h2 id="installing-and-updating" tabindex="-1">Installing and updating <a class="header-anchor" href="#installing-and-updating" aria-label="Permalink to &quot;Installing and updating&quot;">​</a></h2><h3 id="windows-says-it-protected-my-pc" tabindex="-1">Windows says it protected my PC <a class="header-anchor" href="#windows-says-it-protected-my-pc" aria-label="Permalink to &quot;Windows says it protected my PC&quot;">​</a></h3><p>The Windows installer is not yet signed, so SmartScreen warns before it runs. Choose <strong>More info</strong>, then <strong>Run anyway</strong>.</p><h3 id="macos-says-the-app-is-damaged-or-cannot-be-opened" tabindex="-1">macOS says the app is damaged or cannot be opened <a class="header-anchor" href="#macos-says-the-app-is-damaged-or-cannot-be-opened" aria-label="Permalink to &quot;macOS says the app is damaged or cannot be opened&quot;">​</a></h3><p>Versions 0.24.2 and 0.24.3 could be refused on macOS 14 with a message that the app is damaged. This was fixed in 0.24.4: download the newest version from the <a href="https://github.com/Leathercase/leathercase-releases/releases/latest" target="_blank" rel="noreferrer">releases page</a>, drag it to Applications over the old one and open it. The Mac app is signed with an Apple Developer ID and notarised, so it opens without overriding Gatekeeper. It needs macOS 12 or later.</p><h3 id="meaning-search-is-not-offered-on-my-mac" tabindex="-1">Meaning search is not offered on my Mac <a class="header-anchor" href="#meaning-search-is-not-offered-on-my-mac" aria-label="Permalink to &quot;Meaning search is not offered on my Mac&quot;">​</a></h3><p>Intel Macs cannot run the meaning search model. Word search works as always.</p><h3 id="the-linux-deb-does-not-update-itself" tabindex="-1">The Linux <code>.deb</code> does not update itself <a class="header-anchor" href="#the-linux-deb-does-not-update-itself" aria-label="Permalink to &quot;The Linux `.deb` does not update itself&quot;">​</a></h3><p>A package your system installed cannot be replaced by the app, so <strong>Open download page</strong> opens the release instead. Install the new <code>.deb</code> the way you installed the first. The AppImage does update itself.</p><h3 id="how-do-i-uninstall" tabindex="-1">How do I uninstall? <a class="header-anchor" href="#how-do-i-uninstall" aria-label="Permalink to &quot;How do I uninstall?&quot;">​</a></h3><p>See <a href="/guide/reference/updates#uninstalling">Updates and uninstalling</a>. Your writing always stays.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>The agent says</th><th>What to do</th></tr></thead><tbody><tr><td>Leathercase is not running</td><td>Open Leathercase once, then ask again. If it is not installed, the message says where to download it</td></tr><tr><td>It is not connected</td><td>Connect it in Leathercase under the id its settings use</td></tr><tr><td>Its token was refused</td><td>You revoked it, or connected it again since. Connect it again in Leathercase</td></tr></tbody></table><p>ChatGPT cannot connect for now: it reaches only servers on the internet, and Leathercase will not relay your stories through one. See <a href="/guide/guide/connect-an-agent">Connect an agent</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/how-a-story-is-read">How a story is read</a></li><li><a href="/guide/reference/formats">Files Leathercase reads</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/reference/privacy">Privacy</a></li><li><a href="/guide/guide/plot-grid">Plot grid</a></li><li><a href="/guide/guide/connect-an-agent">Connect an agent</a></li></ul>',74)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
